scratch = Path('/tmp/p015-panel-prevalidation')
scratch.mkdir(parents=True, exist_ok=True)
archives = list(Path('/kaggle/input').rglob('panel-material.bin'))
if len(archives) != 1:
    raise RuntimeError('Opaque frozen material missing or ambiguous: ' + str(archives))
if hashlib.sha256(archives[0].read_bytes()).hexdigest() != 'eeebb65c1a03d71d42ed29d6d081b27af59a78a9c1c32ab7593d69b31f6ff8cc':
    raise RuntimeError('Opaque upload bytes differ from frozen original material')
material = scratch / 'material'
material.mkdir(exist_ok=False)
with tarfile.open(archives[0]) as archive:
    archive.extractall(material, filter='data')
for name, expected in EXPECTED_FILES.items():
    path = material / name
    if path.stat().st_size != expected['bytes'] or hashlib.sha256(path.read_bytes()).hexdigest() != expected['sha256']:
        raise RuntimeError('Mounted source differs from frozen material: ' + name)
criteria = json.loads((material / 'host-criteria.json').read_text())['tasks']
tasks_by_iid = {task['iid']: task for task in json.loads((material / 'agent-tasks.json').read_text())}
if len(criteria) != len(tasks_by_iid):
    raise RuntimeError('Task identities and host criteria disagree')
prepared = out / 'prepared-panel-material.tar.gz'
shutil.copyfile(archives[0], prepared)
source_sha256 = hashlib.sha256(prepared.read_bytes()).hexdigest()
(out / 'material-provenance.json').write_text(json.dumps({
    'source_dataset': 'zhuating/p015-natural-pr-material',
    'original_upload_sha256': 'eeebb65c1a03d71d42ed29d6d081b27af59a78a9c1c32ab7593d69b31f6ff8cc',
    'mounted_layout': 'v2 opaque bin with original tar bytes; extracted files hash-checked',
    'verified_file_count': len(EXPECTED_FILES), 'sha256': source_sha256,
    'bytes': prepared.stat().st_size, 'output_archive': 'prepared-panel-material.tar.gz',
    'purpose': 'Frozen train/dev material; unchanged file bytes and assignments.',
}, indent=2) + '\n')
records = []
for item in criteria:
    iid = item['iid']
    run = scratch / 'runs' / iid
    run.mkdir(parents=True, exist_ok=True)
    logs = out / 'logs' / item['split'] / iid
    logs.mkdir(parents=True, exist_ok=True)
    record = {'iid': iid, 'split': item['split'], 'python': sys.version, 'started': time.time()}
    try:
        with tarfile.open(material / 'snapshots' / (iid + '.tar.gz')) as archive:
            archive.extractall(run, filter='data')
        repo = run / 'repo'
        record['head'] = subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=repo, text=True).strip()
        if record['head'] != tasks_by_iid[iid]['base_commit']:
            raise RuntimeError('Snapshot Git HEAD differs from the frozen original base_commit')
        venv = run / 'venv'
        venv_module.EnvBuilder(with_pip=False, system_site_packages=True, symlinks=True).create(venv)
        python = venv / 'bin/python'
        requirement = material / item['environment']['requirements']
        wheels = material / item['environment']['wheelhouse']
        installed = subprocess.run([str(python), '-m', 'pip', 'install', '--no-index', '--no-deps', '--find-links=' + str(wheels), '-r', str(requirement)], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=180)
        (logs / 'install.log').write_text(installed.stdout)
        if installed.returncode:
            raise RuntimeError('Offline dependency installation failed')
        env = dict(os.environ, PYTHONPATH=str(repo), PYTEST_DISABLE_PLUGIN_AUTOLOAD='1',
                   PATH=str(venv / 'bin') + os.pathsep + os.environ.get('PATH', ''))
        origin = subprocess.run([str(python), '-c', 'import importlib.util; print(importlib.util.find_spec(' + repr(item['module']) + ').origin)'], cwd=repo, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        record['module_origin'] = origin.stdout.strip()
        if origin.returncode or not Path(record['module_origin']).is_relative_to(repo):
            raise RuntimeError('Module did not resolve to the current task checkout')
        criterion = subprocess.run(['git', 'apply', str(material / item['criterion_patch_path'])], cwd=repo, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        (logs / 'criterion-apply.log').write_text(criterion.stdout)
        if criterion.returncode:
            raise RuntimeError('Upstream criterion patch did not apply')
        for state in ('buggy', 'reference'):
            if state == 'reference':
                fixed = subprocess.run(['git', 'apply', str(material / item['reference_patch_path'])], cwd=repo, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
                (logs / 'reference-apply.log').write_text(fixed.stdout)
                if fixed.returncode:
                    raise RuntimeError('Upstream reference patch did not apply')
            for group in ('f2p', 'p2p'):
                extra = [arg for plugin in item['environment'].get('pytest_plugins', []) for arg in ('-p', plugin)]
                if item.get(group + '_command'):
                    command = ['/bin/bash', '-c', item[group + '_command']]
                else:
                    command = [str(python), '-m', 'pytest', '-q', '-p', 'no:cacheprovider', '-o', 'addopts=', *extra, *item[group + '_nodes']]
                executed = subprocess.run(command, cwd=repo, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=item.get('timeout', 180))
                (logs / (state + '-' + group + '.log')).write_text(executed.stdout)
                record[state + '_' + group] = {'returncode': executed.returncode, 'nodes': len(item.get(group + '_nodes', [])), 'command': command, 'tail': executed.stdout[-2000:]}
        record['valid_prepost'] = (record['buggy_f2p']['returncode'] == 1 and record['buggy_p2p']['returncode'] == 0 and record['reference_f2p']['returncode'] == 0 and record['reference_p2p']['returncode'] == 0)
    except Exception as error:
        record['execution_error'] = repr(error)
    finally:
        shutil.rmtree(run, ignore_errors=True)
    record['finished'] = time.time()
    records.append(record)
    (out / 'prevalidation-results.json').write_text(json.dumps(records, indent=2) + '\n')
    print(json.dumps(record), flush=True)
print('Actual source-criterion CPU executions:', len(records), flush=True)
